// Alien de cartoon: cabeca verde, olhos grandes e antenas com luz.
// O estado muda os olhos, a boca e a luz das antenas.
function draw(ctx, t, state) {
  const fala = state === "speaking", ouve = state === "listening", erro = state === "error";
  const ocupado = state === "connecting" || state === "starting";
  ctx.translate(0, orb.wave(t, fala ? 4 : 1) * (fala ? 2 : 3));  // flutua

  // Antenas, atras da cabeca
  const luz = erro ? "#FF4D4D" : ouve ? "#5CF2FF" : ocupado ? "#FFD84D" : "#C6FF5C";
  const brilho = erro ? (orb.wave(t, 4) > 0 ? 1 : 0.3)
    : fala ? 0.6 + 0.4 * orb.ping(t, 4) : ouve ? 1 : 0.55 + 0.45 * orb.ping(t);
  for (const s of [-1, 1]) {
    const tx = 96 + s * 34 + s * 4 * orb.wave(t, 1, s > 0 ? 0 : 0.5), ty = 14 + 3 * orb.wave(t, 2);
    ctx.lineCap = "round";
    for (const [cor, largura] of [["#1E4620", 4], ["#7BD96A", 2]]) {
      ctx.strokeStyle = cor; ctx.lineWidth = largura;
      ctx.beginPath(); ctx.moveTo(96 + s * 16, 44); ctx.quadraticCurveTo(96 + s * 30, 30, tx, ty); ctx.stroke();
    }
    ctx.save();
    ctx.shadowColor = luz; ctx.shadowBlur = 14 * brilho;
    orb.circle(ctx, tx, ty, 7, "#1E4620");
    orb.circle(ctx, tx, ty, 5.5, luz);
    ctx.restore();
    ctx.globalAlpha = 0.8 * brilho; orb.circle(ctx, tx - 1.5, ty - 2, 1.8, "#FFFFFF"); ctx.globalAlpha = 1;
  }

  // Cabeca: gota invertida, verde, com contorno escuro
  const cabeca = new Path2D();
  cabeca.moveTo(96, 38);
  cabeca.bezierCurveTo(146, 38, 160, 92, 130, 136);
  cabeca.quadraticCurveTo(110, 166, 96, 166);
  cabeca.quadraticCurveTo(82, 166, 62, 136);
  cabeca.bezierCurveTo(32, 92, 46, 38, 96, 38);
  const g = ctx.createRadialGradient(80, 70, 8, 96, 100, 90);
  g.addColorStop(0, "#B8F59A"); g.addColorStop(0.55, "#6FD45E"); g.addColorStop(1, "#3E9A3A");
  ctx.fillStyle = g; ctx.fill(cabeca);
  ctx.strokeStyle = "#1E4620"; ctx.lineWidth = 3.5; ctx.stroke(cabeca);

  // Bochechas
  ctx.globalAlpha = 0.35;
  orb.circle(ctx, 62, 122, 8, "#FF8FB3"); orb.circle(ctx, 130, 122, 8, "#FF8FB3");
  ctx.globalAlpha = 1;

  // Olhos amendoados (piscam no "pronto", olham em volta ao conectar, X no erro)
  const pisca = state === "idle" && t > 0.86 && t < 0.94;
  const olhar = ocupado ? 6 * orb.wave(t) : 0;
  for (const s of [-1, 1]) {
    ctx.save();
    ctx.translate(96 + s * 26, 100);
    ctx.rotate(s * -0.42);
    if (erro) {
      ctx.strokeStyle = "#111"; ctx.lineWidth = 4; ctx.lineCap = "round";
      ctx.beginPath(); ctx.moveTo(-9, -9); ctx.lineTo(9, 9); ctx.moveTo(9, -9); ctx.lineTo(-9, 9); ctx.stroke();
    } else {
      const ry = pisca ? 1.5 : ouve ? 15 : 12, rx = ouve ? 22 : 20;
      ctx.beginPath(); ctx.ellipse(0, 0, rx, ry, 0, 0, orb.TAU); ctx.fillStyle = "#0E0E14"; ctx.fill();
      if (!pisca) {
        ctx.fillStyle = "#FFFFFF";
        ctx.beginPath(); ctx.ellipse(-7 + olhar, -4, 5, 3.5, 0, 0, orb.TAU); ctx.fill();
        ctx.globalAlpha = 0.7; orb.circle(ctx, 6 + olhar, 4, 2, "#FFFFFF"); ctx.globalAlpha = 1;
      }
    }
    ctx.restore();
  }

  // Boca: sorriso, "o" ouvindo, abre e fecha falando, triste no erro
  ctx.strokeStyle = "#1E4620"; ctx.lineWidth = 3; ctx.lineCap = "round"; ctx.fillStyle = "#3A1020";
  ctx.beginPath();
  if (fala) ctx.ellipse(96, 140, 9, 3 + 7 * orb.ping(t, 4), 0, 0, orb.TAU);
  else if (ouve) ctx.ellipse(96, 140, 4, 5, 0, 0, orb.TAU);
  else if (erro) ctx.arc(96, 150, 10, 1.15 * Math.PI, 1.85 * Math.PI);
  else ctx.arc(96, 132, 10, 0.2 * Math.PI, 0.8 * Math.PI);
  if (fala || ouve) ctx.fill();
  ctx.stroke();
}
